package com.zaxxer.hikari.pool;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.sql.Connection;
import java.util.Properties;

import org.hibernate.service.UnknownUnwrapTypeException;
import org.junit.Test;

import com.zaxxer.hikari.hibernate.HikariConnectionProvider;

import org.hibernate.service.spi.Configurable;

public class TestHibernate
{
   @Test
   public void testConnectionProvider() throws Exception
   {
      HikariConnectionProvider provider = new HikariConnectionProvider();

      Properties props = new Properties();
      props.load(getClass().getResourceAsStream("/hibernate.properties"));

      provider.configure(props);
      Connection connection = provider.getConnection();
      provider.closeConnection(connection);

      assertNotNull(provider.unwrap(HikariConnectionProvider.class));
      assertFalse(provider.supportsAggressiveRelease());

      try {
         provider.unwrap(TestHibernate.class);
         fail("Expected exception");
      }
      catch (UnknownUnwrapTypeException e) {
      }

      provider.stop();
   }

   @Test
   public void testIsUnwrappableAsAndUnwrapForImplementedInterfaces() throws Exception
   {
      HikariConnectionProvider provider = new HikariConnectionProvider();

      // HikariConnectionProvider implements Configurable, so it SHOULD be
      // unwrappable as Configurable. The bug has isAssignableFrom() operands
      // reversed, causing it to return false.
      assertTrue("HikariConnectionProvider should be unwrappable as Configurable",
                 provider.isUnwrappableAs(Configurable.class));

      // unwrap should return the provider itself for Configurable
      Configurable unwrapped = provider.unwrap(Configurable.class);
      assertNotNull("unwrap(Configurable.class) should not return null", unwrapped);
      assertEquals("unwrap(Configurable.class) should return the provider itself",
                   provider, unwrapped);

      // Also test unwrap with the provider's own class
      assertTrue("HikariConnectionProvider should be unwrappable as itself",
                 provider.isUnwrappableAs(HikariConnectionProvider.class));
      assertEquals("unwrap(HikariConnectionProvider.class) should return self",
                   provider, provider.unwrap(HikariConnectionProvider.class));
   }
}

